void InsertSort(int a[], int n)
{
    int i, j, x;
    for (i = 1; i < n; i++) {
        x = a[i];
        j = i - 1;
        while (j >= 0 && a[j] > x) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = x;
    }
}

int Partition(int a[], int low, int high)
{
    int pivot = a[low];
    while (low < high) {
        while (low < high && a[high] >= pivot)
            high--;
        a[low] = a[high];
        while (low < high && a[low] <= pivot)
            low++;
        a[high] = a[low];
    }
    a[low] = pivot;
    return low;
}

void BubbleSort(int a[], int n)
{
    int i, j, t, flag;
    for (i = 1; i < n; i++) {
        flag = 0;
        for (j = 0; j < n - i; j++)
            if (a[j] > a[j + 1]) {
                t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
                flag = 1;
            }
        if (flag == 0)
            break;
    }
}
